#!/usr/bin/env python3
"""export-equals.py <folder>: ONE CASE A FOLDER: TypeScript's `export =` and `import x = require(..)`: a class, a class merged with a namespace, a function, an object, an enum; read by `import = require`, by a default import, by a namespace import, by a plain require; from .cts and .ts files."""
import os, sys

CASES = {'c1': {'lib.cts': 'class Old { v = 7; static s = "s"; } export = Old;\n', 'main.ts': 'import Old = require("./lib.cts"); console.log(new Old().v, Old.s, typeof Old);\n'}, 'c2': {'lib.cts': 'class Old { v = 7; static s = "s"; } namespace Old { export const extra = 1; } export = Old;\n', 'main.ts': 'import Old = require("./lib.cts"); console.log(new Old().v, Old.s, Old.extra, typeof Old);\n'}, 'c3': {'lib.ts': 'class Old { v = 7; static s = "s"; } export = Old;\n', 'main.ts': 'import Old = require("./lib"); console.log(new Old().v, Old.s, typeof Old);\n'}, 'c4': {'lib.cts': 'function f(n: number): number { return n + 1; } export = f;\n', 'main.ts': 'import f = require("./lib.cts"); console.log(f(1), typeof f);\n'}, 'c5': {'lib.cts': 'const o = { a: 1, b(): number { return 2; } }; export = o;\n', 'main.ts': 'import o = require("./lib.cts"); console.log(o.a, o.b(), typeof o);\n'}, 'c6': {'lib.cts': 'class Old { v = 7; static s = "s"; } export = Old;\n', 'main.ts': 'import Old from "./lib.cts"; console.log(new Old().v, Old.s, typeof Old);\n'}, 'c7': {'lib.cts': 'class Old { v = 7; static s = "s"; } export = Old;\n', 'main.ts': 'import * as Old from "./lib.cts"; console.log(typeof Old, Object.keys(Old).join());\n'}, 'c8': {'lib.cts': 'export class A { v = 1; } export const n = 2; export function g(): number { return 3; }\n', 'main.ts': 'import lib = require("./lib.cts"); console.log(new lib.A().v, lib.n, lib.g(), typeof lib);\n'}, 'c9': {'lib.cts': 'export class A { v = 1; } export const n = 2;\n', 'main.ts': 'import { A, n } from "./lib.cts"; console.log(new A().v, n);\n'}, 'c10': {'lib.cts': 'class Old { v = 7; } export = Old;\n', 'main.ts': 'const Old = require("./lib.cts"); console.log(new Old().v, typeof Old);\n'}, 'c11': {'lib.cts': 'enum E { A = 1, B } export = E;\n', 'main.ts': 'import E = require("./lib.cts"); console.log(E.A, E[2], typeof E);\n'}, 'c12': {'lib.cts': 'class Old { v = 7; m(): number { return this.v; } } export = Old;\n', 'main.ts': 'import Old = require("./lib.cts"); function use(o: Old): number { return o.m() + o.v; } class Heir extends Old { w = 1; } console.log(use(new Old()), use(new Heir()), new Heir().w);\n'}}

for case, files in CASES.items():
    for name, text in files.items():
        path = os.path.join(sys.argv[1], case, name)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        open(path, "w").write(text)
